UPDATE lessons SET title='Inverse Investigators: Check Addition and Subtraction',data=json_patch(data,'{"seed_key":"s2-mat-y3-w08-l2","title":"Inverse Investigators: Check Addition and Subtraction","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":8,"lesson_number":2,"duration_minutes":60,"child_mission":"Master inverse investigators: check addition and subtraction using explicit teaching, supported practice and an original challenge.","learning_intention":"We are learning to apply inverse investigators: check addition and subtraction with sound evidence and checking.","success_criteria":["I can explain the core concept with an example.","I can follow a worked example.","I can practise and use feedback.","I can complete my independent challenge.","I can verify and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Key concepts","cards":[{"front":"Addition and subtraction undo each other","back":"The inverse operation reverses an operation. If 468+257=725, taking 257 away from 725 restores 468."},{"front":"Build connected fact families","back":"Three numbers can form two addition and two subtraction equations, even when the numbers are large."},{"front":"Detect an incorrect result","back":"If a calculation is wrong, the inverse will not return the starting amount. Revisit regrouping instead of changing the check to fit."},{"front":"Apply inverse checks to a context","back":"Label what each number represents so your verification reflects the word problem."}]}],"printable_resource":{"title":"Inverse Investigators: Check Addition and Subtraction","instructions":"Read, practise, complete independent work and check.","passage":"The wildlife centre starts with 468 food packets and receives 257 more.","prompts":["Which information matters?","Show a worked strategy.","Attempt the independent task.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Addition and subtraction undo each other","explain":"**Learn:** The inverse operation reverses an operation. If 468+257=725, taking 257 away from 725 restores 468.\n\n**Original source:** The wildlife centre starts with 468 food packets and receives 257 more.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nCheck 725−257=468. This proves the addition using the original quantities.\n\n**GUIDED PRACTICE**\nTry 356+189=545; verify 545−189=356. Check 803−278=525 by 525+278=803. Evaluate a mistaken claim 427+186=603: 603−186=417, not 427; the correct total is 613.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"The inverse operation reverses an operation. If 468+257=725, taking 257 away from 725 restores 468.","check":{"question":"468+257?","options":["715","725","735","825"],"correct_index":1,"explanation":"725. Check 725−257=468. This proves the addition using the original quantities."},"visual_before":[{"episode":{"title":"Learning Inverse Investigators: Check Addition and Subtraction","transcript":"Pip: I added four hundred sixty-eight and two hundred fifty-seven and got seven hundred twenty-five.\nJuno: Use subtraction to see whether the answer reverses properly.\nPip: Seven hundred twenty-five minus two hundred fifty-seven is four hundred sixty-eight.\nJuno: Exactly. Pause and write the other two equations in that fact family.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I added four hundred sixty-eight and two hundred fifty-seven and got seven hundred twenty-five."},{"who":"juno","text":"Use subtraction to see whether the answer reverses properly."},{"who":"pip","text":"Seven hundred twenty-five minus two hundred fifty-seven is four hundred sixty-eight."},{"who":"juno","text":"Exactly. Pause and write the other two equations in that fact family.","pause_after":true}]}]}}]},{"icon":"📖","title":"Build connected fact families","explain":"**Learn:** Three numbers can form two addition and two subtraction equations, even when the numbers are large.\n\n**Original source:** The wildlife centre starts with 468 food packets and receives 257 more.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n468+257=725; 257+468=725; 725−468=257; 725−257=468.\n\n**GUIDED PRACTICE**\nTry 356+189=545; verify 545−189=356. Check 803−278=525 by 525+278=803. Evaluate a mistaken claim 427+186=603: 603−186=417, not 427; the correct total is 613.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Three numbers can form two addition and two subtraction equations, even when the numbers are large.","check":{"question":"Which checks 468+257=725?","options":["725−257=468","725+257=468","468−257=725","257−725=468"],"correct_index":0,"explanation":"725−257=468. 468+257=725; 257+468=725; 725−468=257; 725−257=468."}},{"icon":"✍️","title":"Detect an incorrect result","explain":"**Learn:** If a calculation is wrong, the inverse will not return the starting amount. Revisit regrouping instead of changing the check to fit.\n\n**Original source:** The wildlife centre starts with 468 food packets and receives 257 more.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nSomeone says 468+257=715. But 715−257=458, not 468, so 715 is wrong.\n\n**GUIDED PRACTICE**\nTry 356+189=545; verify 545−189=356. Check 803−278=525 by 525+278=803. Evaluate a mistaken claim 427+186=603: 603−186=417, not 427; the correct total is 613.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"If a calculation is wrong, the inverse will not return the starting amount. Revisit regrouping instead of changing the check to fit.","check":{"question":"356+189?","options":["535","545","555","645"],"correct_index":1,"explanation":"545. Someone says 468+257=715. But 715−257=458, not 468, so 715 is wrong."}},{"icon":"✅","title":"Apply inverse checks to a context","explain":"**Learn:** Label what each number represents so your verification reflects the word problem.\n\n**Original source:** The wildlife centre starts with 468 food packets and receives 257 more.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n725 packets total minus 468 starting packets equals 257 received. Both equations describe the same centre.\n\n**GUIDED PRACTICE**\nTry 356+189=545; verify 545−189=356. Check 803−278=525 by 525+278=803. Evaluate a mistaken claim 427+186=603: 603−186=417, not 427; the correct total is 613.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Label what each number represents so your verification reflects the word problem.","check":{"question":"803−278?","options":["515","525","535","625"],"correct_index":1,"explanation":"525. 725 packets total minus 468 starting packets equals 257 received. Both equations describe the same centre."}}],"worked_example":"## Teacher''s original model\n\nThe wildlife centre starts with 468 food packets and receives 257 more.\n\n**1. Addition and subtraction undo each other:** Check 725−257=468. This proves the addition using the original quantities.\n\n**2. Build connected fact families:** 468+257=725; 257+468=725; 725−468=257; 725−257=468.\n\n**3. Detect an incorrect result:** Someone says 468+257=715. But 715−257=458, not 468, so 715 is wrong.\n\n**4. Apply inverse checks to a context:** 725 packets total minus 468 starting packets equals 257 received. Both equations describe the same centre.\n\nExplain which step verifies the answer.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 200\"><rect width=\"610\" height=\"200\" rx=\"10\" fill=\"#f5f9f6\"/><text x=\"14\" y=\"27\" font-family=\"Arial\" font-size=\"19\" fill=\"#183c30\">Inverse Investigators: Check Addition and Subtraction</text><rect x=\"10\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"16\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Addition and subtra</text><rect x=\"161\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"167\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Build connected fac</text><rect x=\"312\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"318\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Detect an incorrect</text><rect x=\"463\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"469\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Apply inverse check</text></svg>","alt":"Four learning stages for Inverse Investigators: Check Addition and Subtraction","caption":"The worked examples explain each stage."}],"guided_practice":"Try 356+189=545; verify 545−189=356. Check 803−278=525 by 525+278=803. Evaluate a mistaken claim 427+186=603: 603−186=417, not 427; the correct total is 613.","independent_task":"**Community pantry audit:** The pantry stores 587 tins, receives 268 more, then distributes 379 tins. Calculate both steps and write one inverse equation checking each. Explain why the claim 587+268=745 is false. Build a complete four-equation fact family using 587, 268 and their correct sum.","response_prompt":"**Community pantry audit:** The pantry stores 587 tins, receives 268 more, then distributes 379 tins. Calculate both steps and write one inverse equation checking each. Explain why the claim 587+268=745 is false. Build a complete four-equation fact family using 587, 268 and their correct sum.","quiz":[{"type":"multiple_choice","question":"468+257?","options":["715","725","735","825"],"correct_index":1,"explanation":"725 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which checks 468+257=725?","options":["725−257=468","725+257=468","468−257=725","257−725=468"],"correct_index":0,"explanation":"725−257=468 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"356+189?","options":["535","545","555","645"],"correct_index":1,"explanation":"545 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"803−278?","options":["515","525","535","625"],"correct_index":1,"explanation":"525 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"427+186?","options":["603","613","623","713"],"correct_index":1,"explanation":"613 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"587+268?","options":["845","855","865","955"],"correct_index":1,"explanation":"855 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"855−379?","options":["466","476","486","576"],"correct_index":1,"explanation":"476 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which checks 855−379=476?","options":["476+379=855","476−379=855","855+379=476","379−476=855"],"correct_index":0,"explanation":"476+379=855 is correct; compare with the relevant worked example."},{"type":"short_answer","question":"Complete the independent inverse investigators: check addition and subtraction task with the required steps and evidence.","sample_answer":"587+268=855 tins. After distributing 379, 855−379=476 remain. Addition check: 855−268=587; subtraction check: 476+379=855.","marking_guide":"Check every part of the independent question, accurate calculations or facts and supporting steps.","explanation":"Require a complete, accurate explanation."},{"type":"short_answer","question":"Explain an important check or limitation for inverse investigators: check addition and subtraction.","sample_answer":"587+268=855, not 745, because the tens and ones require regrouping. Fact family: 587+268=855, 268+587=855, 855−587=268, 855−268=587.","marking_guide":"Look for an accurate topic-specific check or justified limitation.","explanation":"A check should connect to the evidence."}],"parent_notes":"Parent: Require an independent attempt and check how the learner reached an answer.\n\nParent: Model answer 1. 587+268=855 tins. After distributing 379, 855−379=476 remain. Addition check: 855−268=587; subtraction check: 476+379=855.\n\nParent: Model answer 2. 587+268=855, not 745, because the tens and ones require regrouping. Fact family: 587+268=855, 268+587=855, 855−587=268, 855−268=587.\n\nParent: Record the learner''s work and check written answers separately. NESA alignment remains unverified.","evidence_instructions":"Keep guided practice, your independent task, one correction and both written responses.","offline_alternative":"Complete the original tasks on paper and save a photograph or parent observation.","extension":"Develop and check a new inverse investigators: check addition and subtraction challenge.","stage_hints":{"accept":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."],"teach0":["Read the Addition and subtraction undo each other instructions.","Find the exact example detail needed for addition and subtraction undo each other.","Explain a method or quote the clue, then check the response."],"teach1":["Read the Build connected fact families instructions.","Find the exact example detail needed for build connected fact families.","Explain a method or quote the clue, then check the response."],"teach2":["Read the Detect an incorrect result instructions.","Find the exact example detail needed for detect an incorrect result.","Explain a method or quote the clue, then check the response."],"teach3":["Read the Apply inverse checks to a context instructions.","Find the exact example detail needed for apply inverse checks to a context.","Explain a method or quote the clue, then check the response."],"learn":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."],"guided":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."],"write":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."],"quiz":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."],"submit":["Read the Inverse Investigators: Check Addition and Subtraction instructions.","Find the exact example detail needed for inverse investigators: check addition and subtraction.","Explain a method or quote the clue, then check the response."]}}') WHERE seed_key='s2-mat-y3-w08-l2';
UPDATE lessons SET title='Two-Step Challenge: Follow the Story',data=json_patch(data,'{"seed_key":"s2-mat-y3-w08-l3","title":"Two-Step Challenge: Follow the Story","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":8,"lesson_number":3,"duration_minutes":60,"child_mission":"Master two-step challenge: follow the story using explicit teaching, supported practice and an original challenge.","learning_intention":"We are learning to apply two-step challenge: follow the story with sound evidence and checking.","success_criteria":["I can explain the core concept with an example.","I can follow a worked example.","I can practise and use feedback.","I can complete my independent challenge.","I can verify and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Key concepts","cards":[{"front":"Identify the question and order","back":"Underline quantities and events. If tickets are printed then sold, the amount changes twice."},{"front":"Write a two-step plan","back":"Addition models an increase; subtraction models what is used or removed. Label the intermediate total."},{"front":"Calculate accurately with place value","back":"Work one operation at a time; regroup when needed and carry units correctly."},{"front":"Use an estimate and inverse check","back":"An estimate gives a reasonable scale, and an inverse check confirms each exact stage."}]}],"printable_resource":{"title":"Two-Step Challenge: Follow the Story","instructions":"Read, practise, complete independent work and check.","passage":"A school fair has 325 tickets before lunch, prints 180 more and sells 267.","prompts":["Which information matters?","Show a worked strategy.","Attempt the independent task.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify the question and order","explain":"**Learn:** Underline quantities and events. If tickets are printed then sold, the amount changes twice.\n\n**Original source:** A school fair has 325 tickets before lunch, prints 180 more and sells 267.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nInitial 325; 180 printed; 267 sold. The question asks what remains.\n\n**GUIDED PRACTICE**\nA class has 218 pencils, buys 145 and hands out 176. Available: 218+145=363; remaining: 363−176=187. Check 187+176=363. Explain why adding all three numbers would incorrectly treat handed-out pencils as new supplies.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Underline quantities and events. If tickets are printed then sold, the amount changes twice.","check":{"question":"325+180?","options":["495","505","515","605"],"correct_index":1,"explanation":"505. Initial 325; 180 printed; 267 sold. The question asks what remains."},"visual_before":[{"episode":{"title":"Learning Two-Step Challenge: Follow the Story","transcript":"Pip: The fair printed tickets and then sold some. Can I add all three numbers?\nJuno: Tickets printed increase the total; tickets sold reduce it.\nPip: So three hundred twenty-five plus one hundred eighty, then subtract two hundred sixty-seven.\nJuno: Good. Pause and estimate the result before calculating exactly.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"The fair printed tickets and then sold some. Can I add all three numbers?"},{"who":"juno","text":"Tickets printed increase the total; tickets sold reduce it."},{"who":"pip","text":"So three hundred twenty-five plus one hundred eighty, then subtract two hundred sixty-seven."},{"who":"juno","text":"Good. Pause and estimate the result before calculating exactly.","pause_after":true}]}]}}]},{"icon":"📖","title":"Write a two-step plan","explain":"**Learn:** Addition models an increase; subtraction models what is used or removed. Label the intermediate total.\n\n**Original source:** A school fair has 325 tickets before lunch, prints 180 more and sells 267.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n325+180=505 tickets available, then 505−267=238 tickets left.\n\n**GUIDED PRACTICE**\nA class has 218 pencils, buys 145 and hands out 176. Available: 218+145=363; remaining: 363−176=187. Check 187+176=363. Explain why adding all three numbers would incorrectly treat handed-out pencils as new supplies.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Addition models an increase; subtraction models what is used or removed. Label the intermediate total.","check":{"question":"505−267?","options":["228","238","248","338"],"correct_index":1,"explanation":"238. 325+180=505 tickets available, then 505−267=238 tickets left."}},{"icon":"✍️","title":"Calculate accurately with place value","explain":"**Learn:** Work one operation at a time; regroup when needed and carry units correctly.\n\n**Original source:** A school fair has 325 tickets before lunch, prints 180 more and sells 267.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n505−267 requires exchange across zero: 4 hundreds, 9 tens, 15 ones. Subtract to get 238.\n\n**GUIDED PRACTICE**\nA class has 218 pencils, buys 145 and hands out 176. Available: 218+145=363; remaining: 363−176=187. Check 187+176=363. Explain why adding all three numbers would incorrectly treat handed-out pencils as new supplies.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Work one operation at a time; regroup when needed and carry units correctly.","check":{"question":"218+145?","options":["353","363","373","463"],"correct_index":1,"explanation":"363. 505−267 requires exchange across zero: 4 hundreds, 9 tens, 15 ones. Subtract to get 238."}},{"icon":"✅","title":"Use an estimate and inverse check","explain":"**Learn:** An estimate gives a reasonable scale, and an inverse check confirms each exact stage.\n\n**Original source:** A school fair has 325 tickets before lunch, prints 180 more and sells 267.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nAbout 300+200−300=200, close to 238. Verify 238+267=505, then 505−180=325.\n\n**GUIDED PRACTICE**\nA class has 218 pencils, buys 145 and hands out 176. Available: 218+145=363; remaining: 363−176=187. Check 187+176=363. Explain why adding all three numbers would incorrectly treat handed-out pencils as new supplies.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"An estimate gives a reasonable scale, and an inverse check confirms each exact stage.","check":{"question":"363−176?","options":["177","187","197","287"],"correct_index":1,"explanation":"187. About 300+200−300=200, close to 238. Verify 238+267=505, then 505−180=325."}}],"worked_example":"## Teacher''s original model\n\nA school fair has 325 tickets before lunch, prints 180 more and sells 267.\n\n**1. Identify the question and order:** Initial 325; 180 printed; 267 sold. The question asks what remains.\n\n**2. Write a two-step plan:** 325+180=505 tickets available, then 505−267=238 tickets left.\n\n**3. Calculate accurately with place value:** 505−267 requires exchange across zero: 4 hundreds, 9 tens, 15 ones. Subtract to get 238.\n\n**4. Use an estimate and inverse check:** About 300+200−300=200, close to 238. Verify 238+267=505, then 505−180=325.\n\nExplain which step verifies the answer.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 200\"><rect width=\"610\" height=\"200\" rx=\"10\" fill=\"#f5f9f6\"/><text x=\"14\" y=\"27\" font-family=\"Arial\" font-size=\"19\" fill=\"#183c30\">Two-Step Challenge: Follow the Story</text><rect x=\"10\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"16\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Identify the questi</text><rect x=\"161\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"167\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Write a two-step pl</text><rect x=\"312\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"318\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Calculate accuratel</text><rect x=\"463\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"469\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Use an estimate and</text></svg>","alt":"Four learning stages for Two-Step Challenge: Follow the Story","caption":"The worked examples explain each stage."}],"guided_practice":"A class has 218 pencils, buys 145 and hands out 176. Available: 218+145=363; remaining: 363−176=187. Check 187+176=363. Explain why adding all three numbers would incorrectly treat handed-out pencils as new supplies.","independent_task":"**School garden supplies:** Volunteers begin with 475 seedlings, receive 286 more and plant 398. How many remain? Show two equations with labels, one nearest-hundred estimate, and an inverse check. Then create your own two-step problem with an increase followed by a decrease and solve it. Explain why subtracting 398 before adding 286 could produce a confusing intermediate negative quantity in some scenarios, even when the final arithmetic is equivalent.","response_prompt":"**School garden supplies:** Volunteers begin with 475 seedlings, receive 286 more and plant 398. How many remain? Show two equations with labels, one nearest-hundred estimate, and an inverse check. Then create your own two-step problem with an increase followed by a decrease and solve it. Explain why subtracting 398 before adding 286 could produce a confusing intermediate negative quantity in some scenarios, even when the final arithmetic is equivalent.","quiz":[{"type":"multiple_choice","question":"325+180?","options":["495","505","515","605"],"correct_index":1,"explanation":"505 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"505−267?","options":["228","238","248","338"],"correct_index":1,"explanation":"238 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"218+145?","options":["353","363","373","463"],"correct_index":1,"explanation":"363 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"363−176?","options":["177","187","197","287"],"correct_index":1,"explanation":"187 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"475+286?","options":["751","761","771","861"],"correct_index":1,"explanation":"761 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"761−398?","options":["353","363","373","463"],"correct_index":1,"explanation":"363 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which operation represents planting seedlings?","options":["Subtract from available seedlings","Add more seedlings","Multiply by two","Ignore planted number"],"correct_index":0,"explanation":"Subtract from available seedlings is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which inverse checks 761−398=363?","options":["363+398=761","363−398=761","761+398=363","398−363=761"],"correct_index":0,"explanation":"363+398=761 is correct; compare with the relevant worked example."},{"type":"short_answer","question":"Complete the independent two-step challenge: follow the story task with the required steps and evidence.","sample_answer":"475+286=761 seedlings available; 761−398=363 remain. Estimate 500+300−400≈400. Inverse check 363+398=761 and 761−286=475.","marking_guide":"Check every part of the independent question, accurate calculations or facts and supporting steps.","explanation":"Require a complete, accurate explanation."},{"type":"short_answer","question":"Explain an important check or limitation for two-step challenge: follow the story.","sample_answer":"I follow the event order so each intermediate amount has a real-world meaning. The total 475+286−398 equals 363 either way algebraically, but subtracting 398 before the delivery would suggest only 77 seedlings remained before the shipment; in other examples the intermediate could be negative. My new example: 240+130−185=185.","marking_guide":"Look for an accurate topic-specific check or justified limitation.","explanation":"A check should connect to the evidence."}],"parent_notes":"Parent: Require an independent attempt and check how the learner reached an answer.\n\nParent: Model answer 1. 475+286=761 seedlings available; 761−398=363 remain. Estimate 500+300−400≈400. Inverse check 363+398=761 and 761−286=475.\n\nParent: Model answer 2. I follow the event order so each intermediate amount has a real-world meaning. The total 475+286−398 equals 363 either way algebraically, but subtracting 398 before the delivery would suggest only 77 seedlings remained before the shipment; in other examples the intermediate could be negative. My new example: 240+130−185=185.\n\nParent: Record the learner''s work and check written answers separately. NESA alignment remains unverified.","evidence_instructions":"Keep guided practice, your independent task, one correction and both written responses.","offline_alternative":"Complete the original tasks on paper and save a photograph or parent observation.","extension":"Develop and check a new two-step challenge: follow the story challenge.","stage_hints":{"accept":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."],"teach0":["Read the Identify the question and order instructions.","Find the exact example detail needed for identify the question and order.","Explain a method or quote the clue, then check the response."],"teach1":["Read the Write a two-step plan instructions.","Find the exact example detail needed for write a two-step plan.","Explain a method or quote the clue, then check the response."],"teach2":["Read the Calculate accurately with place value instructions.","Find the exact example detail needed for calculate accurately with place value.","Explain a method or quote the clue, then check the response."],"teach3":["Read the Use an estimate and inverse check instructions.","Find the exact example detail needed for use an estimate and inverse check.","Explain a method or quote the clue, then check the response."],"learn":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."],"guided":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."],"write":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."],"quiz":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."],"submit":["Read the Two-Step Challenge: Follow the Story instructions.","Find the exact example detail needed for two-step challenge: follow the story.","Explain a method or quote the clue, then check the response."]}}') WHERE seed_key='s2-mat-y3-w08-l3';
UPDATE lessons SET title='Addition and Subtraction Checkpoint: Show What You Know',data=json_patch(data,'{"seed_key":"s2-mat-y3-w08-l4","title":"Addition and Subtraction Checkpoint: Show What You Know","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":8,"lesson_number":4,"duration_minutes":60,"child_mission":"Master addition and subtraction checkpoint: show what you know using explicit teaching, supported practice and an original challenge.","learning_intention":"We are learning to apply addition and subtraction checkpoint: show what you know with sound evidence and checking.","success_criteria":["I can explain the core concept with an example.","I can follow a worked example.","I can practise and use feedback.","I can complete my independent challenge.","I can verify and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Key concepts","cards":[{"front":"Read the numbers and events","back":"Locate the quantities and determine whether each event adds to or subtracts from the current total."},{"front":"Estimate the answer before calculating","back":"Rounding to hundreds creates a benchmark for a sensible result."},{"front":"Calculate with written methods","back":"Align place values and handle exchanges across zeros when subtracting."},{"front":"Verify and reflect on errors","back":"Check both operations with their inverses. Explain the exact part you would revisit if a result disagrees."}]}],"printable_resource":{"title":"Addition and Subtraction Checkpoint: Show What You Know","instructions":"Read, practise, complete independent work and check.","passage":"A community library reports 1,204 books, receives 368 and lends 495.","prompts":["Which information matters?","Show a worked strategy.","Attempt the independent task.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Read the numbers and events","explain":"**Learn:** Locate the quantities and determine whether each event adds to or subtracts from the current total.\n\n**Original source:** A community library reports 1,204 books, receives 368 and lends 495.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nStart with 1,204; receiving 368 increases the stock to 1,572; lending 495 removes that amount from the shelves.\n\n**GUIDED PRACTICE**\nCheckpoint warm-up: 437+285=722 (regroup ones and tens); 900−456=444 (exchange across zeros); 564+189−275=478. Verify 478+275=753 and 753−189=564. Explain why 900−456=544 is incorrect.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Locate the quantities and determine whether each event adds to or subtracts from the current total.","check":{"question":"1,204+368?","options":["1,472","1,572","1,672","1,582"],"correct_index":1,"explanation":"1,572. Start with 1,204; receiving 368 increases the stock to 1,572; lending 495 removes that amount from the shelves."},"visual_before":[{"episode":{"title":"Learning Addition and Subtraction Checkpoint: Show What You Know","transcript":"Pip: I can estimate, but does that mean I can skip exact calculations?\nJuno: No. Estimation checks the scale; written methods find the exact answer.\nPip: I''ll show each exchange and use the inverse to verify it.\nJuno: Pause and estimate one thousand two hundred four plus three hundred sixty-eight.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I can estimate, but does that mean I can skip exact calculations?"},{"who":"juno","text":"No. Estimation checks the scale; written methods find the exact answer."},{"who":"pip","text":"I''ll show each exchange and use the inverse to verify it."},{"who":"juno","text":"Pause and estimate one thousand two hundred four plus three hundred sixty-eight.","pause_after":true}]}]}}]},{"icon":"📖","title":"Estimate the answer before calculating","explain":"**Learn:** Rounding to hundreds creates a benchmark for a sensible result.\n\n**Original source:** A community library reports 1,204 books, receives 368 and lends 495.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n1,204≈1,200; 368≈400; 495≈500. Estimated books remaining on shelves: about 1,100.\n\n**GUIDED PRACTICE**\nCheckpoint warm-up: 437+285=722 (regroup ones and tens); 900−456=444 (exchange across zeros); 564+189−275=478. Verify 478+275=753 and 753−189=564. Explain why 900−456=544 is incorrect.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Rounding to hundreds creates a benchmark for a sensible result.","check":{"question":"1,572−495?","options":["1,067","1,077","1,087","1,177"],"correct_index":1,"explanation":"1,077. 1,204≈1,200; 368≈400; 495≈500. Estimated books remaining on shelves: about 1,100."}},{"icon":"✍️","title":"Calculate with written methods","explain":"**Learn:** Align place values and handle exchanges across zeros when subtracting.\n\n**Original source:** A community library reports 1,204 books, receives 368 and lends 495.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n1,204+368=1,572. Then 1,572−495=1,077. Check each column carefully.\n\n**GUIDED PRACTICE**\nCheckpoint warm-up: 437+285=722 (regroup ones and tens); 900−456=444 (exchange across zeros); 564+189−275=478. Verify 478+275=753 and 753−189=564. Explain why 900−456=544 is incorrect.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Align place values and handle exchanges across zeros when subtracting.","check":{"question":"437+285?","options":["712","722","732","822"],"correct_index":1,"explanation":"722. 1,204+368=1,572. Then 1,572−495=1,077. Check each column carefully."}},{"icon":"✅","title":"Verify and reflect on errors","explain":"**Learn:** Check both operations with their inverses. Explain the exact part you would revisit if a result disagrees.\n\n**Original source:** A community library reports 1,204 books, receives 368 and lends 495.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\n1,077+495=1,572; 1,572−368=1,204. If an answer is 1,177, check the subtraction hundreds column.\n\n**GUIDED PRACTICE**\nCheckpoint warm-up: 437+285=722 (regroup ones and tens); 900−456=444 (exchange across zeros); 564+189−275=478. Verify 478+275=753 and 753−189=564. Explain why 900−456=544 is incorrect.\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Check both operations with their inverses. Explain the exact part you would revisit if a result disagrees.","check":{"question":"900−456?","options":["434","444","454","544"],"correct_index":1,"explanation":"444. 1,077+495=1,572; 1,572−368=1,204. If an answer is 1,177, check the subtraction hundreds column."}}],"worked_example":"## Teacher''s original model\n\nA community library reports 1,204 books, receives 368 and lends 495.\n\n**1. Read the numbers and events:** Start with 1,204; receiving 368 increases the stock to 1,572; lending 495 removes that amount from the shelves.\n\n**2. Estimate the answer before calculating:** 1,204≈1,200; 368≈400; 495≈500. Estimated books remaining on shelves: about 1,100.\n\n**3. Calculate with written methods:** 1,204+368=1,572. Then 1,572−495=1,077. Check each column carefully.\n\n**4. Verify and reflect on errors:** 1,077+495=1,572; 1,572−368=1,204. If an answer is 1,177, check the subtraction hundreds column.\n\nExplain which step verifies the answer.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 200\"><rect width=\"610\" height=\"200\" rx=\"10\" fill=\"#f5f9f6\"/><text x=\"14\" y=\"27\" font-family=\"Arial\" font-size=\"19\" fill=\"#183c30\">Addition and Subtraction Checkpoint: Show What You Know</text><rect x=\"10\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"16\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Read the numbers an</text><rect x=\"161\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"167\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Estimate the answer</text><rect x=\"312\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"318\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Calculate with writ</text><rect x=\"463\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"469\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Verify and reflect </text></svg>","alt":"Four learning stages for Addition and Subtraction Checkpoint: Show What You Know","caption":"The worked examples explain each stage."}],"guided_practice":"Checkpoint warm-up: 437+285=722 (regroup ones and tens); 900−456=444 (exchange across zeros); 564+189−275=478. Verify 478+275=753 and 753−189=564. Explain why 900−456=544 is incorrect.","independent_task":"**Independent checkpoint:** (1) Calculate 608+475 and check by subtraction. (2) Calculate 1,002−586, showing exchanges across zeros, then check by addition. (3) A collection has 786 cans, gains 247 and gives away 359; find the remainder with two labelled equations. (4) Round each answer to the nearest hundred. (5) Choose one error you corrected and explain its cause.","response_prompt":"**Independent checkpoint:** (1) Calculate 608+475 and check by subtraction. (2) Calculate 1,002−586, showing exchanges across zeros, then check by addition. (3) A collection has 786 cans, gains 247 and gives away 359; find the remainder with two labelled equations. (4) Round each answer to the nearest hundred. (5) Choose one error you corrected and explain its cause.","quiz":[{"type":"multiple_choice","question":"1,204+368?","options":["1,472","1,572","1,672","1,582"],"correct_index":1,"explanation":"1,572 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"1,572−495?","options":["1,067","1,077","1,087","1,177"],"correct_index":1,"explanation":"1,077 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"437+285?","options":["712","722","732","822"],"correct_index":1,"explanation":"722 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"900−456?","options":["434","444","454","544"],"correct_index":1,"explanation":"444 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"608+475?","options":["1,073","1,083","1,093","1,183"],"correct_index":1,"explanation":"1,083 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"1,002−586?","options":["406","416","426","516"],"correct_index":1,"explanation":"416 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"786+247?","options":["1,023","1,033","1,043","1,133"],"correct_index":1,"explanation":"1,033 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"1,033−359?","options":["664","674","684","774"],"correct_index":1,"explanation":"674 is correct; compare with the relevant worked example."},{"type":"short_answer","question":"Complete the independent addition and subtraction checkpoint: show what you know task with the required steps and evidence.","sample_answer":"608+475=1,083, check 1,083−475=608. 1,002−586=416, check 416+586=1,002. 786+247=1,033; 1,033−359=674 cans remain.","marking_guide":"Check every part of the independent question, accurate calculations or facts and supporting steps.","explanation":"Require a complete, accurate explanation."},{"type":"short_answer","question":"Explain an important check or limitation for addition and subtraction checkpoint: show what you know.","sample_answer":"To nearest hundred: 1,083→1,100; 416→400; 674→700. The zeros in 1,002 require borrowing through the hundreds and tens when subtracting 586. I check by adding 416+586=1,002.","marking_guide":"Look for an accurate topic-specific check or justified limitation.","explanation":"A check should connect to the evidence."}],"parent_notes":"Parent: Require an independent attempt and check how the learner reached an answer.\n\nParent: Model answer 1. 608+475=1,083, check 1,083−475=608. 1,002−586=416, check 416+586=1,002. 786+247=1,033; 1,033−359=674 cans remain.\n\nParent: Model answer 2. To nearest hundred: 1,083→1,100; 416→400; 674→700. The zeros in 1,002 require borrowing through the hundreds and tens when subtracting 586. I check by adding 416+586=1,002.\n\nParent: Record the learner''s work and check written answers separately. NESA alignment remains unverified.","evidence_instructions":"Keep guided practice, your independent task, one correction and both written responses.","offline_alternative":"Complete the original tasks on paper and save a photograph or parent observation.","extension":"Develop and check a new addition and subtraction checkpoint: show what you know challenge.","stage_hints":{"accept":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."],"teach0":["Read the Read the numbers and events instructions.","Find the exact example detail needed for read the numbers and events.","Explain a method or quote the clue, then check the response."],"teach1":["Read the Estimate the answer before calculating instructions.","Find the exact example detail needed for estimate the answer before calculating.","Explain a method or quote the clue, then check the response."],"teach2":["Read the Calculate with written methods instructions.","Find the exact example detail needed for calculate with written methods.","Explain a method or quote the clue, then check the response."],"teach3":["Read the Verify and reflect on errors instructions.","Find the exact example detail needed for verify and reflect on errors.","Explain a method or quote the clue, then check the response."],"learn":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."],"guided":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."],"write":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."],"quiz":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."],"submit":["Read the Addition and Subtraction Checkpoint: Show What You Know instructions.","Find the exact example detail needed for addition and subtraction checkpoint: show what you know.","Explain a method or quote the clue, then check the response."]}}') WHERE seed_key='s2-mat-y3-w08-l4';
UPDATE lessons SET title='Read the Visual: Diagrams, Graphs and Captions',data=json_patch(data,'{"seed_key":"s2-eng-y3-w09-l1","title":"Read the Visual: Diagrams, Graphs and Captions","stage":"Stage 2","learning_area":"English","year_level":3,"week":9,"lesson_number":1,"duration_minutes":60,"child_mission":"Master read the visual: diagrams, graphs and captions using explicit teaching, supported practice and an original challenge.","learning_intention":"We are learning to apply read the visual: diagrams, graphs and captions with sound evidence and checking.","success_criteria":["I can explain the core concept with an example.","I can follow a worked example.","I can practise and use feedback.","I can complete my independent challenge.","I can verify and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Key concepts","cards":[{"front":"Read the title and labels","back":"A visual text gives information through labelled pictures, diagrams, charts and graphs. Read its heading, axes, units and categories before interpreting."},{"front":"Extract a precise fact","back":"Look at the value shown for a specific category, and use the correct unit."},{"front":"Compare categories and explain","back":"A reader can identify the most, least and difference by comparing the actual labelled values."},{"front":"Write an accurate caption","back":"A caption briefly explains what the visual shows and should avoid claims the graph does not support."}]}],"printable_resource":{"title":"Read the Visual: Diagrams, Graphs and Captions","instructions":"Read, practise, complete independent work and check.","passage":"A school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.","prompts":["Which information matters?","Show a worked strategy.","Attempt the independent task.","Explain how you checked."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Read the title and labels","explain":"**Learn:** A visual text gives information through labelled pictures, diagrams, charts and graphs. Read its heading, axes, units and categories before interpreting.\n\n**Original source:** A school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nA graph titled Birds Observed has categories for each type and a vertical axis counting birds. The number 8 means eight magpies observed, not eight bird species.\n\n**GUIDED PRACTICE**\nundefined\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"A visual text gives information through labelled pictures, diagrams, charts and graphs. Read its heading, axes, units and categories before interpreting.","check":{"question":"How many magpies recorded?","options":["3","5","6","8"],"correct_index":3,"explanation":"8. A graph titled Birds Observed has categories for each type and a vertical axis counting birds. The number 8 means eight magpies observed, not eight bird species."},"visual_before":[{"episode":{"title":"Learning Read the Visual: Diagrams, Graphs and Captions","transcript":"Pip: The tallest bar shows eight magpies. Does that mean there are eight bird species?\nJuno: Read the title, categories and units. It counts individual birds observed.\nPip: So I can compare eight magpies with three kookaburras.\nJuno: Yes. Pause and calculate the difference, then write a careful caption.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"The tallest bar shows eight magpies. Does that mean there are eight bird species?"},{"who":"juno","text":"Read the title, categories and units. It counts individual birds observed."},{"who":"pip","text":"So I can compare eight magpies with three kookaburras."},{"who":"juno","text":"Yes. Pause and calculate the difference, then write a careful caption.","pause_after":true}]}]}}]},{"icon":"📖","title":"Extract a precise fact","explain":"**Learn:** Look at the value shown for a specific category, and use the correct unit.\n\n**Original source:** A school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nThe bar for lorikeets reaches five, so five lorikeets were observed. The bar for kookaburras reaches three.\n\n**GUIDED PRACTICE**\nundefined\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"Look at the value shown for a specific category, and use the correct unit.","check":{"question":"How many lorikeets recorded?","options":["3","5","6","8"],"correct_index":1,"explanation":"5. The bar for lorikeets reaches five, so five lorikeets were observed. The bar for kookaburras reaches three."}},{"icon":"✍️","title":"Compare categories and explain","explain":"**Learn:** A reader can identify the most, least and difference by comparing the actual labelled values.\n\n**Original source:** A school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nMagpies 8 versus kookaburras 3 gives a difference of five. The graph cannot explain *why* one bird was seen more often.\n\n**GUIDED PRACTICE**\nundefined\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"A reader can identify the most, least and difference by comparing the actual labelled values.","check":{"question":"Which bird is least observed?","options":["Kookaburras","Magpies","Cockatoos","Lorikeets"],"correct_index":0,"explanation":"Kookaburras. Magpies 8 versus kookaburras 3 gives a difference of five. The graph cannot explain *why* one bird was seen more often."}},{"icon":"✅","title":"Write an accurate caption","explain":"**Learn:** A caption briefly explains what the visual shows and should avoid claims the graph does not support.\n\n**Original source:** A school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.\n\n**Why it matters:** Find the exact detail or number supporting this idea.","example":"**WORKED THINKING**\nCaption: ''Number of four bird types recorded in a school survey.'' I avoid claiming there are only four kinds of birds in Australia.\n\n**GUIDED PRACTICE**\nundefined\n\n**CHECK:** Locate any place your answer differs from the method, and revise it.","notice":"A caption briefly explains what the visual shows and should avoid claims the graph does not support.","check":{"question":"How many more magpies than kookaburras?","options":["3","4","5","6"],"correct_index":2,"explanation":"5. Caption: ''Number of four bird types recorded in a school survey.'' I avoid claiming there are only four kinds of birds in Australia."}}],"worked_example":"## Teacher''s original model\n\nA school survey shows four native birds observed: magpies 8, lorikeets 5, kookaburras 3 and cockatoos 6. A column graph uses one symbol per bird counted.\n\n**1. Read the title and labels:** A graph titled Birds Observed has categories for each type and a vertical axis counting birds. The number 8 means eight magpies observed, not eight bird species.\n\n**2. Extract a precise fact:** The bar for lorikeets reaches five, so five lorikeets were observed. The bar for kookaburras reaches three.\n\n**3. Compare categories and explain:** Magpies 8 versus kookaburras 3 gives a difference of five. The graph cannot explain *why* one bird was seen more often.\n\n**4. Write an accurate caption:** Caption: ''Number of four bird types recorded in a school survey.'' I avoid claiming there are only four kinds of birds in Australia.\n\nExplain which step verifies the answer.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 610 200\"><rect width=\"610\" height=\"200\" rx=\"10\" fill=\"#f5f9f6\"/><text x=\"14\" y=\"27\" font-family=\"Arial\" font-size=\"19\" fill=\"#183c30\">Read the Visual: Diagrams, Graphs and Captions</text><rect x=\"10\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"16\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Read the title and </text><rect x=\"161\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"167\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Extract a precise f</text><rect x=\"312\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e1eee4\"/><text x=\"318\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Compare categories </text><rect x=\"463\" y=\"57\" width=\"140\" height=\"108\" rx=\"9\" fill=\"#e7ecf9\"/><text x=\"469\" y=\"108\" font-family=\"Arial\" font-size=\"12\" fill=\"#263b32\">Write an accurate c</text></svg>","alt":"Four learning stages for Read the Visual: Diagrams, Graphs and Captions","caption":"The worked examples explain each stage."}],"independent_task":"**Create and interpret a graph:** Use this supplied dataset for a class garden count: butterflies 7, ladybirds 4, bees 9 and dragonflies 2. Draw or type a labelled bar chart with a clear title and scale, then write a one-sentence caption. Answer: which is most, least, how many more bees than dragonflies, and total insects counted. Explain one conclusion the graph does NOT establish.","response_prompt":"**Create and interpret a graph:** Use this supplied dataset for a class garden count: butterflies 7, ladybirds 4, bees 9 and dragonflies 2. Draw or type a labelled bar chart with a clear title and scale, then write a one-sentence caption. Answer: which is most, least, how many more bees than dragonflies, and total insects counted. Explain one conclusion the graph does NOT establish.","quiz":[{"type":"multiple_choice","question":"How many magpies recorded?","options":["3","5","6","8"],"correct_index":3,"explanation":"8 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"How many lorikeets recorded?","options":["3","5","6","8"],"correct_index":1,"explanation":"5 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which bird is least observed?","options":["Kookaburras","Magpies","Cockatoos","Lorikeets"],"correct_index":0,"explanation":"Kookaburras is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"How many more magpies than kookaburras?","options":["3","4","5","6"],"correct_index":2,"explanation":"5 is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"What does a caption do?","options":["Briefly explain the visual","Replace all labels","Invent unrelated facts","Show only the author''s opinion"],"correct_index":0,"explanation":"Briefly explain the visual is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"What should a graph have?","options":["Clear title, labels and scale","Only bright colours","No units","An unrelated story"],"correct_index":0,"explanation":"Clear title, labels and scale is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Which statement is unsupported?","options":["The survey recorded 8 magpies","Three kookaburras were observed","The graph proves all Australian birds have these counts","Six cockatoos were observed"],"correct_index":2,"explanation":"The graph proves all Australian birds have these counts is correct; compare with the relevant worked example."},{"type":"multiple_choice","question":"Total birds in the survey?","options":["20","21","22","23"],"correct_index":2,"explanation":"22 is correct; compare with the relevant worked example."},{"type":"short_answer","question":"Complete the independent read the visual: diagrams, graphs and captions task with the required steps and evidence.","sample_answer":"Bar chart: Garden Insects Observed, with counts butterflies 7, ladybirds 4, bees 9, dragonflies 2. Caption: ''Number of four insect types seen during a class garden observation.'' Most: bees (9); fewest: dragonflies (2); difference: 7; total 22.","marking_guide":"Check every part of the independent question, accurate calculations or facts and supporting steps.","explanation":"Require a complete, accurate explanation."},{"type":"short_answer","question":"Explain an important check or limitation for read the visual: diagrams, graphs and captions.","sample_answer":"The chart describes this one observation only. It cannot prove there are more bees than dragonflies in every garden or that these counts stay the same each day. The title and scale should communicate the specific dataset.","marking_guide":"Look for an accurate topic-specific check or justified limitation.","explanation":"A check should connect to the evidence."}],"parent_notes":"Parent: Require an independent attempt and check how the learner reached an answer.\n\nParent: Model answer 1. Bar chart: Garden Insects Observed, with counts butterflies 7, ladybirds 4, bees 9, dragonflies 2. Caption: ''Number of four insect types seen during a class garden observation.'' Most: bees (9); fewest: dragonflies (2); difference: 7; total 22.\n\nParent: Model answer 2. The chart describes this one observation only. It cannot prove there are more bees than dragonflies in every garden or that these counts stay the same each day. The title and scale should communicate the specific dataset.\n\nParent: Record the learner''s work and check written answers separately. NESA alignment remains unverified.","evidence_instructions":"Keep guided practice, your independent task, one correction and both written responses.","offline_alternative":"Complete the original tasks on paper and save a photograph or parent observation.","extension":"Develop and check a new read the visual: diagrams, graphs and captions challenge.","stage_hints":{"accept":["Read the Read the Visual: Diagrams, Graphs and Captions instructions.","Find the exact example detail needed for read the visual: diagrams, graphs and captions.","Explain a method or quote the clue, then check the response."],"teach0":["Read the Read the title and labels instructions.","Find the exact example detail needed for read the title and labels.","Explain a method or quote the clue, then check the response."],"teach1":["Read the Extract a precise fact instructions.","Find the exact example detail needed for extract a precise fact.","Explain a method or quote the clue, then check the response."],"teach2":["Read the Compare categories and explain instructions.","Find the exact example detail needed for compare categories and explain.","Explain a method or quote the clue, then check the response."],"teach3":["Read the Write an accurate caption instructions.","Find the exact example detail needed for write an accurate caption.","Explain a method or quote the clue, then check the response."],"learn":["Read the Read the Visual: Diagrams, Graphs and Captions instructions.","Find the exact example detail needed for read the visual: diagrams, graphs and captions.","Explain a method or quote the clu